@transforms.add
def handle_keyed_by(config, jobs):
    """Resolve fields that can be keyed by platform, etc."""
    for job in jobs:
        resolve_keyed_by(
            job,
            "locale-list",
            item_name=job["name"],
            **{
                "release-type": config.params["release_type"],
                "release-level": release_level(config.graph_config["release-branches"], config.params),
                "project": config.params["project"],
            },
        )

        for item in ["comm-locales-file", "browser-locales-file", "run.config"]:
            resolve_keyed_by(
                job,
                item,
                item_name=job["name"],
                **{
                    "project": config.params["project"],
                }
            )

        yield job


@transforms.add
def make_job_description(config, jobs):
    for job in jobs:
        locale_list = job.pop("locale-list")
        comm_locales_file = job.pop("comm-locales-file")
        browser_locales_file = job.pop("browser-locales-file")
        job["run"].update(
            {
                "job-script": "comm/taskcluster/scripts/build-l10n-pre.sh",
                "options": [
                    f"locale-list={locale_list}",
                    f"comm-locales-file={comm_locales_file}",
                    f"browser-locales-file={browser_locales_file}",
                ],
            }
        )

        job["run-on-repo-type"] = ["hg"]

        yield job
